/** Why medal budget may remain after allocation completes. */
export type BotMedalBudgetStopReason =
  | 'invalid_inputs'
  | 'complete'
  | 'tier_admission_blocked'
  | 'no_upgrade_candidates'

/** Shared planner thresholds — single source for Vue compute and future bot reuse. */
export const BOT_MEDAL_PLANNER_THRESHOLDS = {
  secondarySyncedDurationLagLevels: 4,
  naturalSyncTargetToleranceSeconds: 0.75,
  maxRecommendedAddedCooldownLabs: 2,
  minMeaningfulTierEntryObjectiveDelta: 0.015,
  primaryCompletionMaxRemainingLevels: 1,
  primaryDurationAdmissionMaxRemainingLevels: 3,
  priorityRangeAnchorToleranceMeters: 0.25,
  /**
   * Coordinate-ascent rounds around the exact knapsack solve.
   *
   * Each round re-measures every stat ladder against the previous round's plan, so rounds
   * only buy anything where rows are coupled — the Bot Bot's amplification and the timing
   * terms. A round that does not improve the true objective is discarded and ends the loop,
   * so this is a ceiling rather than a count.
   *
   * This replaced `plannerLookaheadDepth`, `plannerBeamWidth`, `plannerMaxBatches`,
   * `plannerMaxBundleCandidates` and two beam delta floors. A knapsack has no beam to widen
   * and no candidate list to cap: it considers every option at every budget.
   */
  coordinateAscentRounds: 6,
  effectivePathForwardStepCount: 30,
  /** Penalize uptime ratios above this target (duration/cooldown). */
  dutyCycleOvershootTarget: 0.92,
} as const

/**
 * Which bots start out kept in step with which, before the player says otherwise.
 *
 * Golden, Amplify and the Bot Bot begin as one group because the Bot Bot amplifies the other
 * two, and an amplifier is worth nothing during a window where nothing is being amplified.
 * Flame and Thunder begin alone: their value is damage reduction and crowd control, which
 * pays whenever they are up rather than when they happen to be up alongside something else,
 * so uptime beats alignment for them.
 *
 * Those are DEFAULTS. A build that wants Flame and Thunder aligned with each other and
 * nothing else can say so, which is why this is a graph of partners rather than a single
 * in-or-out flag — one flag put every bot that opted in into the same group by construction.
 *
 * Edges are read both ways, so the two halves of a pair only have to agree that they are one.
 */
export const DEFAULT_BOT_SYNC_PARTNERS: Readonly<Record<string, readonly string[]>> = {
  'Golden Bot': ['Amplify Bot', 'Bot Bot'],
  'Amplify Bot': ['Golden Bot', 'Bot Bot'],
  'Bot Bot': ['Golden Bot', 'Amplify Bot'],
  'Flame Bot': [],
  'Thunder Bot': [],
}

/**
 * The connected components of the sync graph, with singletons dropped.
 *
 * A bot on its own is not "a group of one" — it is a bot whose cadence nothing else has a
 * claim on, and the knapsack buys its cooldown on merit. Only groups of two or more get a
 * shared cadence locked for them.
 */
export function resolveBotSyncGroups(
  labels: readonly string[],
  partnersFor: (botLabel: string) => readonly string[],
): string[][] {
  const present = new Set(labels)
  const edges = new Map<string, Set<string>>()
  for (const label of labels) edges.set(label, new Set())
  for (const label of labels) {
    for (const partner of partnersFor(label)) {
      if (partner === label || !present.has(partner)) continue
      edges.get(label)!.add(partner)
      edges.get(partner)!.add(label)
    }
  }
  const seen = new Set<string>()
  const groups: string[][] = []
  for (const label of labels) {
    if (seen.has(label)) continue
    const component: string[] = []
    const queue = [label]
    seen.add(label)
    while (queue.length) {
      const current = queue.shift()!
      component.push(current)
      for (const next of edges.get(current) ?? []) {
        if (seen.has(next)) continue
        seen.add(next)
        queue.push(next)
      }
    }
    if (component.length > 1) groups.push(component)
  }
  return groups
}


/**
 * How the medals lean before the player touches anything.
 *
 * These were all 1 — an even fifth each — which is not a neutral position, it is the claim
 * that every bot is worth the same. Thunder in particular collected a full share for crowd
 * control that most builds are not buying medals for.
 *
 * Golden and the Bot Bot are level with each other because they work as a pair: the Bot Bot's
 * whole value is amplifying what Golden is doing. Amplify takes a real share below them, Flame
 * a little, and Thunder almost none.
 *
 * A starting position, not a claim. The Medal Share sliders exist to move it, and a build that
 * is leaning on Thunder's crowd control should.
 */
export const DEFAULT_BOT_VALUE_WEIGHTS: Readonly<Record<string, number>> = {
  'Golden Bot': 1,
  'Bot Bot': 1,
  'Amplify Bot': 0.6,
  'Flame Bot': 0.25,
  'Thunder Bot': 0.05,
}
